use cyberdeck_core::gps::{Fix,FixHistory,ObservationCursor};
#[test]fn observations_use_the_fix_near_receive_time(){let mut history=FixHistory::<4>::new();history.push(&Fix{received_ms:1000,latitude_e7:10,..Fix::default()});history.push(&Fix{received_ms:5000,latitude_e7:50,..Fix::default()});assert_eq!(history.closest(1100,500).unwrap().latitude_e7,10);assert!(history.closest(3000,500).is_none());}
#[test]fn cached_device_is_not_relocated_at_later_fixes(){let mut cursor=ObservationCursor::<4>::new();assert!(cursor.accept("BLE:AA",1000,1200,1500));assert!(!cursor.accept("BLE:AA",1000,2000,1500));assert!(!cursor.accept("BLE:AA",1000,9000,1500));assert!(cursor.accept("BLE:AA",8900,9000,1500));}
#[test]fn histories_and_cursors_stay_bounded(){let mut history=FixHistory::<2>::new();let mut cursor=ObservationCursor::<2>::new();for n in 1..20{history.push(&Fix{received_ms:n,..Fix::default()});cursor.accept(&format!("{n}"),n,n,1);}assert_eq!(history.len(),2);assert_eq!(cursor.len(),2);assert!(history.closest(1,0).is_none());}
#[test]fn unchanged_fix_replaces_metadata_without_growing_history(){let mut history=FixHistory::<2>::new();history.push(&Fix{received_ms:10,satellites:1,..Fix::default()});history.push(&Fix{received_ms:10,satellites:7,..Fix::default()});assert_eq!(history.len(),1);assert_eq!(history.closest(10,0).unwrap().satellites,7);}
